import { DOCUMENT_KINDS, expect, expectStatus, test } from "../../fixtures";

test("Approving every extraction approves the vendor", { tag: "@REV-05" }, async ({ apiAs, factory }) => {
  // Arrange
  const reviewer = await apiAs("reviewer");
  const { vendor, extractions } = await factory.vendorInReview({ name: `REV-05 ${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}` });

  // Act
  for (const kind of DOCUMENT_KINDS) {
    const decided = await expectStatus(
      await reviewer.post(`/api/extractions/${extractions[kind].id}/decision`, { data: { decision: "approve" } }),
      200,
    );
    expect(decided.status, `${kind} extraction is approved`).toBe("approved");
  }

  // Assert
  await expect
    .poll(async () => (await expectStatus(await reviewer.get(`/api/vendors/${vendor.id}`), 200)).status, {
      message: "the stored vendor status becomes approved",
    })
    .toBe("approved");
  const audit = await expectStatus<{ items: { action: string }[] }>(await reviewer.get(`/api/vendors/${vendor.id}/audit`), 200);
  expect(audit.items.map((e) => e.action)).toContain("vendor.approved");
});
